return ['domain'=>'ecomiq-for-woocommerce','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_EC','project-id-version'=>'Ecomiq for WooCommerce','messages'=>['Ecomiq for WooCommerce'=>'Ecomiq para WooCommerce','Connect your store to Ecomiq in one click to sync products, stock, prices and orders.'=>'Conecta tu tienda con Ecomiq en un clic para sincronizar productos, stock, precios y pedidos.','Use an address like https://admin.ecomiq.pe, without a path.'=>'Usa una dirección como https://admin.ecomiq.pe, sin ruta.','WooCommerce could not create the API key.'=>'WooCommerce no pudo crear la clave de API.','The authorization code is invalid or expired. Connect again from Ecomiq.'=>'El código de autorización no es válido o venció. Vuelve a conectar desde Ecomiq.','WordPress does not detect HTTPS, so WooCommerce will reject the API key.'=>'WordPress no detecta HTTPS, así que WooCommerce rechazará la clave de API.','Settings'=>'Ajustes','You are not allowed to connect this store.'=>'No tienes permiso para conectar esta tienda.','Connect %s to Ecomiq'=>'Conectar %s con Ecomiq','Ecomiq will be able to read and update products, stock, prices and orders.'=>'Ecomiq podrá leer y actualizar productos, stock, precios y pedidos.','Ecomiq store'=>'Tienda en Ecomiq','Access as'=>'Acceso como','Returns to'=>'Vuelve a','This replaces the current connection.'=>'Reemplaza la conexión actual.','This replaces the current connection with %s.'=>'Reemplaza la conexión actual con %s.','Approve'=>'Aprobar','Cancel'=>'Cancelar','The link is incomplete or expired. Start again from Ecomiq.'=>'El enlace está incompleto o venció. Vuelve a empezar desde Ecomiq.','This request wants to return to %1$s, but this store only trusts %2$s. Do not approve it.'=>'Esta solicitud quiere volver a %1$s, pero esta tienda solo confía en %2$s. No la apruebes.','If you are testing your own Ecomiq installation, change the address under Advanced.'=>'Si pruebas tu propia instalación de Ecomiq, cambia la dirección en Avanzado.','Invalid request'=>'Solicitud no válida','Back'=>'Volver','Connect to Ecomiq'=>'Conectar con Ecomiq','Sync products, stock, prices and orders of %s with Ecomiq.'=>'Sincroniza productos, stock, precios y pedidos de %s con Ecomiq.','WordPress does not detect HTTPS. WooCommerce rejects API keys without it.'=>'WordPress no detecta HTTPS. WooCommerce rechaza las claves de API sin HTTPS.','Turn on permalinks in Settings → Permalinks.'=>'Activa los enlaces permanentes en Ajustes → Enlaces permanentes.','Connect'=>'Conectar','Advanced'=>'Avanzado','Ecomiq address'=>'Dirección de Ecomiq','Save'=>'Guardar','Change it only to test your own Ecomiq installation.'=>'Cámbiala solo para probar tu propia instalación de Ecomiq.','Connected to Ecomiq'=>'Conectada con Ecomiq','Ecomiq syncs products, stock, prices and orders of %s.'=>'Ecomiq sincroniza productos, stock, precios y pedidos de %s.','Not yet'=>'Todavía no','%s ago'=>'hace %s','Last access'=>'Último acceso','API key'=>'Clave de API','%1$s by %2$s'=>'%1$s por %2$s','Connected on'=>'Conectada el','Open Ecomiq'=>'Abrir Ecomiq','Disconnect'=>'Desconectar','Disconnect from Ecomiq?'=>'¿Desconectar de Ecomiq?','Ecomiq stops syncing this store. Its API key and webhooks are deleted. Your products and orders do not change.'=>'Ecomiq deja de sincronizar esta tienda. Se borran su clave de API y sus webhooks. Tus productos y pedidos no cambian.','Disconnected from Ecomiq.'=>'Desconectada de Ecomiq.','Address saved.'=>'Dirección guardada.']];
